// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CampaignWikiPage) predicate.CampaignWikiPage {
	return predicate.CampaignWikiPage(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CampaignWikiPage) predicate.CampaignWikiPage {
	return predicate.CampaignWikiPage(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CampaignWikiPage) predicate.CampaignWikiPage {
	return predicate.CampaignWikiPage(sql.NotPredicates(p))
}
